 const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',book:'M3 4h5a5 5 0 0 1 4 2v15a5 5 0 0 0-4-2H3z M21 4h-5a5 5 0 0 0-4 2 M12 21a5 5 0 0 1 4-2h5V4',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',play:'M8 5l11 7-11 7z',chart:'M4 20h17 M7 16v-5 M12 16V4 M17 16V8',users:'M15 21v-2a5 5 0 0 0-5-5H8a5 5 0 0 0-5 5v2 M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M17 3a4 4 0 0 1 0 8 M21 21v-2a5 5 0 0 0-3-4',check:'M4 12l5 5L20 6',arrow:'M18 12H5 M11 6l-6 6 6 6',star:'M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',shield:'M12 2l9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',info:'M12 8v.1 M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M5 5l14 14 M19 5L5 19',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v7H6z',send:'M21 3L9 15 M21 3l-5 18-5-8-8-5z',target:'M20 12a8 8 0 1 1-8-8 M16 12a4 4 0 1 1-4-4 M12 12l9-9 M16 3h5v5',seed:'M12 21v-8 M12 15C2 15 2 6 2 6s10-1 10 9 M12 12c0-9 10-10 10-10s1 10-10 10',window:'M4 3h16v18H4z M4 12h16 M12 3v18',refresh:'M20 7a9 9 0 1 0 1 8 M20 2v6h-6',fullscreen:'M4 9V4h5 M15 4h5v5 M20 15v5h-5 M9 20H4v-5',pause:'M8 4v16 M16 4v16',up:'M6 15l6-6 6 6',down:'M6 9l6 6 6-6',folder:'M3 5h7l2 3h9v12H3z',flag:'M5 21V3 M5 3c4-3 9 3 14 0v10c-5 3-10-3-14 0',link:'M9 15l6-6 M7 14l-2 2a4 4 0 0 0 6 6l3-3 M10 5l3-3a4 4 0 0 1 6 6l-3 3'};
 const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
 const e=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const n=x=>new Intl.NumberFormat('ar-QA').format(x),uid=prefix=>prefix+'-'+(globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2));
 let storageWarning='',S=C.initial();
 try{const t=localStorage.getItem(KEY);if(t){const v=JSON.parse(t);if(v.schema===1&&Array.isArray(v.assignments)&&Array.isArray(v.responses)&&v.students?.length===3)S=v;else storageWarning='لم نعتمد البيانات المحلية غير المتوافقة. افتتحت مساحة تجربة جديدة.';}}catch{storageWarning='الحفظ الدائم غير متاح في هذا المتصفح. تبقى التجربة عاملة، ويمكن تنزيل نسخة من البيانات.';}
 const V={unit:'u1',tab:'book',query:'',skill:'all',selected:[...D.defaultTaskIds],learner:'demo-1',context:'class',font:17,quizId:null,qi:0,selection:null,retry:false,hinted:false,reportStudent:'demo-1',game:null,observation:{},time:0,running:false,timerAt:0,scope:'all',activeLesson:S.selectedLesson||'u1-l1',lastLesson:null,classIndex:0};
 const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S));}catch{storageWarning='تعذر الحفظ الدائم على هذا الجهاز. نزّلي بيانات التجربة قبل إغلاق الصفحة.';}};
 const route=()=>{const a=(location.hash||'#teacher/home').slice(1).split('/');return {role:['teacher','student','family'].includes(a[0])?a[0]:'teacher',page:a[1]||'home',id:a.slice(2).join('/')};};
 const go=(path)=>{if(location.hash==='#'+path)render();else location.hash=path;};
 const notify=msg=>{const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),3600);};
 const act=(name,text,cls='btn',extras='')=>`<button type="button" class="${cls}" data-do="${name}" ${extras}>${text}</button>`;
