 const link=(path,text,cls='btn secondary')=>`<a class="${cls}" href="#${path}">${text}</a>`;
 const qby=id=>C.question(D,id),student=()=>S.students.find(s=>s.id===V.learner),readiness=()=>S.students.map(st=>C.summary(S,D,st.id));

