 function shell(content,r){
  const navs=r.role==='teacher'?[["home","رفيق المعلمة","home"],["curriculum","منهجي","book"],["class","إتقان | 45","clock"],["play","إتقان | PLAY","play"],["library","رفوف","folder"],["review","إجابات الطالبات","users"],["reports","نبض الأسرة","chart"]]:r.role==='student'?[["home","مهمتي اليوم","home"],["curriculum","منهجي","book"],["library","رفوف","folder"],["progress","تقدمي","chart"]]:[["home","نبض الأسرة","chart"]];
  app.innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#${r.role}/home"><img src="assets/school.webp" alt="شعار مدرسة السلام"><div><strong>إتقان <span style="color:#dcb887">| نبض</span></strong><small>من التدريب إلى الاستقلال</small></div></a><div class="side-label">مساحة ${r.role==='teacher'?'المعلمة':r.role==='student'?'الطالبة':'الأسرة'}</div><nav class="nav" aria-label="التنقل الرئيسي">${navs.map(([page,label,ico])=>`<a href="#${r.role}/${page}" class="${r.page===page||r.page==='lesson'&&page==='curriculum'?'active':''}" ${r.page===page?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${r.page===page?'<i class="nav-dot"></i>':''}</a>`).join('')}</nav><div class="side-bottom"><div class="side-note">${icon('seed')}<b style="font-size:.81rem"> كل حصة تترك أثرًا</b><p>المنهج أولًا. ثم تدريب هادف، وشاهد مستقل على الفهم.</p></div><div class="side-sign">إعداد: أ. نوف الغرينيق<br>الصف الخامس · الفصل الأول</div></div></aside><div class="stage"><header class="topbar"><div class="context"><span class="avatar">ن</span><div><strong>${r.role==='teacher'?e(D.teacher):r.role==='student'?'أهلًا '+e(student().name):'إتقان | نبض الأسرة'}</strong><small>اللغة العربية · الصف الخامس · <bdi>${D.academicYear}</bdi></small></div></div><div class="mode-switch" aria-label="تبديل دور التجربة">${[['teacher','المعلمة'],['student','الطالبة'],['family','الأسرة']].map(([role,t])=>act('role',t,role===r.role?'active':'',`data-role="${role}"`)).join('')}</div></header><main id="main" class="workspace" tabindex="-1"><div class="demo-banner">${icon('shield')}<span>تجربة قبول بلا تسجيل دخول · أسماء افتراضية · الحفظ على هذا المتصفح فقط، وليس بين الأجهزة.</span><a href="#" data-do="about">حدود النسخة</a></div>${storageWarning?`<div class="notice error">${e(storageWarning)}</div>`:''}${content}<footer class="footnote"><span>${e(D.school)} · مبادرة تعليمية مساندة</span><span>V9 · المنهج المعتمد · لا درجات رسمية في هذه التجربة</span></footer></main></div></div>`;
 }
